void InsertNode(LinkList head,ListNode *p)
{
    ListNode *p1,*p2;
    p1=head; p2=p1->next;
    while(p2!=NULL && (strcmp(p2->data.num,p->data.num)<0))
    {
    p1=p2;    /*p1指向刚访问过的节点*/
    p2=p2->next;    /*p2指向表的下一个节点*/
    }
    p1->next=p;    /*插入p所指向的节点*/
    p->next=p2;    /*连接表中的剩余部分*/
}
